import {describe, expect, it, jest} from '@jest/globals';
import {Ajv} from 'ajv';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry static validation', () => {
  it('reuses the registered static validator across ten calls (specs/hal-engine-tool-input-validation/spec.md#6)', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      const registry = new ToolRegistry();
      const schema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
      const readSchema = jest.fn(() => schema);
      const execute = jest.fn(async () => 'sunny');
      registry.register(
        {name: 'weather', description: 'Weather forecast', get inputSchema() { return readSchema(); }},
        execute
      );

      for (let call = 0; call < 10; call++) {
        await registry.execute('weather', {location: 'Berlin'});
      }

      expect({compiles: compile.mock.calls.length, reads: readSchema.mock.calls.length, calls: execute.mock.calls.length})
        .toEqual({compiles: 1, reads: 1, calls: 10});
    } finally {
      compile.mockRestore();
    }
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.static.test.ts --runInBand"
